const express = require('express');
const { z } = require('zod');
const { DynamicStructuredTool } = require('@langchain/core/tools');
const { requireEngineerAuth } = require('../auth/guard');
const k8sClient = require('../services/k8s');

const app = express();
app.use(express.json());

app.post('/api/agent/tools/pod-logs', requireEngineerAuth, async (req, res) => {
  const { toolArgs } = req.body;
  try {
    const { clusterId, namespace } = toolArgs || {};
    // Verify caller has authorized RBAC permissions for target cluster and namespace
    const hasAccess = req.user.authorizedClusters?.some(
      c => c.clusterId === clusterId && (c.namespaces.includes('*') || c.namespaces.includes(namespace))
    );

    if (!hasAccess) {
      return res.status(403).json({ error: 'Forbidden: Insufficient cluster RBAC permissions' });
    }

    const fetchPodLogsTool = new DynamicStructuredTool({
      name: 'fetch_pod_logs',
      description: 'Fetches standard output and error logs from a running container pod',
      schema: z.object({
        clusterId: z.string(),
        namespace: z.string(),
        podName: z.string()
      }),
      func: async ({ clusterId, namespace, podName }) => {
        return await k8sClient.getPodLogs(clusterId, namespace, podName);
      }
    });

    const logs = await fetchPodLogsTool.invoke(toolArgs);
    res.json({ logs });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

app.listen(8117);
